        // print the normalized linear approximation table
        System.out.println("\nNormalized Linear Approximation Table:");
        for(int i = 0; i < 8; i++) {
            for(int j = 0; j < 8; j++) {
                System.out.print(nlat[i][j] + "\t");
            }
            System.out.println();
        }
    }

    public static int lat(int[][] input, int[][] output, int[] sbox, int a, int b) {
        int count = 0;
        for(int x = 0; x < 8; x++) {
            int fx = sbox[input[x][0]*4 + input[x][1]*2 + input[x][2]];
            int lsum = a*input[x][0] ^ a*input[x][1] ^ a*input[x][2] ^ b*fx;
            int osum = output[x][0]*lsum ^ output[x][1]*lsum ^ output[x][2]*lsum;
            if(osum == 0) {
                count++;
            }
        }
        return count;
    }
